import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
// Start Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// End Google Fonts Loader



export type CartoonEyesProps = Record<string, any>;

const CartoonEyes: React.FC<CartoonEyesProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 8,
  eyeSize = 300,
  pupilSize = 80,
  eyeSeparation = 40,
  strokeWidth = 12,
  eyeColor = "#ffffff",
  pupilColor = "#000000",
}) => {
  useFontLoader(["Fredoka One"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background Logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timing Constants
  const T = fps; // 1 second in frames

  // --- PUPIL MOVEMENT (X AXIS) ---
  // Sequence: Center -> Left -> Right -> Center
  const pupilMoveX = interpolate(
    frame,
    [
      0,          // Start Center
      1 * T,      // Start moving Left
      1.5 * T,    // Arrive Left
      2.5 * T,    // Start moving Right
      3.2 * T,    // Arrive Right (pass center)
      4.2 * T,    // Start moving Center
      4.8 * T,    // Arrive Center
    ],
    [0, 0, -1, -1, 1, 1, 0],
    {
      easing: Easing.bezier(0.25, 1, 0.5, 1),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // --- PUPIL MOVEMENT (Y AXIS) ---
  // Sequence: Center -> Up -> Down -> Center
  const pupilMoveY = interpolate(
    frame,
    [
      0,          // Start Center
      5.0 * T,    // Start moving Up
      5.5 * T,    // Arrive Up
      6.5 * T,    // Start moving Down
      7.0 * T,    // Arrive Down (pass center)
      7.5 * T,    // Start moving Center
      8.0 * T,    // Arrive Center
    ],
    [0, 0, -1, -1, 0.8, 0.8, 0],
    {
      easing: Easing.bezier(0.25, 1, 0.5, 1),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // --- BLINK ANIMATION ---
  // Occasional blinks at specific timestamps
  // Blink 1 at ~0.5s, Blink 2 at ~3.5s, Blink 3 at ~6.5s
  const blinkDuration = 0.15 * T; // Fast blink
  
  const createBlink = (startFrame: number) => {
    return interpolate(
      frame,
      [startFrame, startFrame + blinkDuration / 2, startFrame + blinkDuration],
      [0, 1, 0],
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }
    );
  };

  const blink1 = createBlink(0.5 * T);
  const blink2 = createBlink(3.5 * T);
  const blink3 = createBlink(6.0 * T); // Sync with looking down slightly

  // Combine blinks (max value wins)
  const currentBlinkState = Math.max(blink1, blink2, blink3);

  // Derived dimensions
  const maxPupilOffset = (eyeSize / 2) - (pupilSize / 2) - strokeWidth * 1.5;
  const currentPupilX = pupilMoveX * maxPupilOffset;
  const currentPupilY = pupilMoveY * maxPupilOffset;

  // Eyelid masking calculation
  // 0 = open, 1 = closed
  const eyelidHeight = interpolate(currentBlinkState, [0, 1], [0, eyeSize]);

  // Render a single eye
  const renderEye = (isLeft: boolean) => {
    return (
      <div
        style={{
          width: eyeSize,
          height: eyeSize,
          position: "relative",
          borderRadius: "50%",
          backgroundColor: eyeColor,
          border: `${strokeWidth}px solid black`,
          overflow: "hidden", // Masks the pupil and eyelid
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          boxSizing: "border-box",
        }}
      >
        {/* Pupil */}
        <div
          style={{
            width: pupilSize,
            height: pupilSize,
            borderRadius: "50%",
            backgroundColor: pupilColor,
            position: "absolute",
            transform: `translate(${currentPupilX}px, ${currentPupilY}px)`,
          }}
        />

        {/* Shine on Pupil (Cartoon detail) */}
        <div
            style={{
                width: pupilSize * 0.3,
                height: pupilSize * 0.3,
                borderRadius: "50%",
                backgroundColor: "white",
                position: "absolute",
                transform: `translate(${currentPupilX + pupilSize * 0.2}px, ${currentPupilY - pupilSize * 0.2}px)`,
                opacity: 0.8
            }}
        />

        {/* Upper Eyelid */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            height: eyelidHeight / 2, // Meets in middle
            backgroundColor: eyeColor, // Or skin color, but keeping it flat white/bg color usually looks best for simple eyes
            borderBottom: currentBlinkState > 0.1 ? `${strokeWidth}px solid black` : "none",
            zIndex: 10,
            width: "120%", // wider to avoid gaps
            marginLeft: "-10%"
          }}
        />

        {/* Lower Eyelid */}
        <div
            style={{
                position: "absolute",
                bottom: 0,
                left: 0,
                width: "120%",
                marginLeft: "-10%",
                height: eyelidHeight / 2,
                backgroundColor: eyeColor,
                borderTop: currentBlinkState > 0.1 ? `${strokeWidth}px solid black` : "none",
                zIndex: 10,
            }}
        />
      </div>
    );
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Fredoka One",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          gap: eyeSeparation,
          flexDirection: "row",
          alignItems: "center",
        }}
      >
        {renderEye(true)}
        {renderEye(false)}
      </div>
    </AbsoluteFill>
  );
};

export default CartoonEyes;